alter table public.productos add column if not exists stock integer not null default 0 check(stock>=0); alter table public.productos add column if not exists tipo text not null default 'normal' check(tipo in('normal','oferta','combo')); alter table public.productos add column if not exists precio_oferta numeric check(precio_oferta is null or precio_oferta>=0);
create table if not exists public.ventas(id uuid primary key default gen_random_uuid(),admin_id uuid not null references auth.users(id),total numeric not null default 0,notas text,created_at timestamptz not null default now()); create table if not exists public.venta_items(id uuid primary key default gen_random_uuid(),venta_id uuid not null references public.ventas(id) on delete cascade,producto_id uuid not null references public.productos(id),cantidad integer not null check(cantidad>0),precio_unitario numeric not null);
alter table public.ventas enable row level security; alter table public.venta_items enable row level security;
create or replace function public.registrar_venta(p_items jsonb,p_notas text default null) returns uuid language plpgsql security definer set search_path='' as $$ declare v uuid; i jsonb; p public.productos%rowtype; q integer; price numeric; total numeric:=0; begin if (select auth.uid()) is null then raise exception 'No autorizado'; end if; insert into public.ventas(admin_id,notas) values((select auth.uid()),p_notas) returning id into v; for i in select * from jsonb_array_elements(p_items) loop q:=(i->>'cantidad')::integer; select * into p from public.productos where id=(i->>'producto_id')::uuid for update; if not found or q<1 or p.stock<q then raise exception 'Stock insuficiente'; end if; price:=coalesce(case when p.tipo='oferta' then p.precio_oferta end,p.precio,0); update public.productos set stock=stock-q,disponible=case when stock-q=0 then false else disponible end where id=p.id; insert into public.venta_items(venta_id,producto_id,cantidad,precio_unitario) values(v,p.id,q,price); total:=total+price*q; end loop; update public.ventas set total=total where id=v; return v; end; $$; revoke execute on function public.registrar_venta(jsonb,text) from public,anon; grant execute on function public.registrar_venta(jsonb,text) to authenticated;